import{_ as a,c as l,o as i,a3 as r}from"./chunks/framework.BurWKwwG.js";const p=JSON.parse('{"title":"浏览与分析","description":"","frontmatter":{},"headers":[],"relativePath":"zh/3.3_browse.md","filePath":"zh/3.3_browse.md"}'),t={name:"zh/3.3_browse.md"};function n(o,e,s,h,c,d){return i(),l("div",null,e[0]||(e[0]=[r('<h1 id="浏览与分析" tabindex="-1">浏览与分析 <a class="header-anchor" href="#浏览与分析" aria-label="Permalink to “浏览与分析”">​</a></h1><h2 id="生物标志物浏览器" tabindex="-1">生物标志物浏览器 <a class="header-anchor" href="#生物标志物浏览器" aria-label="Permalink to “生物标志物浏览器”">​</a></h2><p>Biomarker 页面（<code>/biomarker</code>）提供整理的结直肠癌生物标志物数据库的结构化访问，以分页表格形式展示所有记录。</p><h2 id="gene-expression-atlas-umap-单细胞基因表达可视化" tabindex="-1">Gene Expression Atlas（UMAP 单细胞基因表达可视化） <a class="header-anchor" href="#gene-expression-atlas-umap-单细胞基因表达可视化" aria-label="Permalink to “Gene Expression Atlas（UMAP 单细胞基因表达可视化）”">​</a></h2><p>路径：<code>/explore</code></p><ul><li><strong>筛选器</strong>：Dataset 选择、Cell Type 选择</li><li><strong>功能</strong>：基于 UMAP 降维的细胞分布图，默认加载 10000 个细胞</li><li><strong>基因表达叠加</strong>：选择基因后，UMAP 图上以颜色梯度展示该基因的表达水平</li><li><strong>交互</strong>：支持缩放、平移</li></ul><h2 id="protein-interaction-network-蛋白质互作网络" tabindex="-1">Protein Interaction Network（蛋白质互作网络） <a class="header-anchor" href="#protein-interaction-network-蛋白质互作网络" aria-label="Permalink to “Protein Interaction Network（蛋白质互作网络）”">​</a></h2><p>路径：<code>/explore/network</code></p><ul><li><strong>功能</strong>：基于 Cytoscape.js 的 PPI 蛋白质互作网络浏览</li><li><strong>交互</strong>：支持缩放、平移、节点拖拽</li></ul><h2 id="single-cell-analyses-单细胞分析" tabindex="-1">Single-Cell Analyses（单细胞分析） <a class="header-anchor" href="#single-cell-analyses-单细胞分析" aria-label="Permalink to “Single-Cell Analyses（单细胞分析）”">​</a></h2><p>路径：<code>/analysis</code>，包含以下 7 个分析模块：</p><h3 id="degs-差异表达基因" tabindex="-1">DEGs（差异表达基因） <a class="header-anchor" href="#degs-差异表达基因" aria-label="Permalink to “DEGs（差异表达基因）”">​</a></h3><p>三个选项卡：</p><ul><li><strong>Original</strong>：按 Cell Type 的火山图（全量散点数据渲染，不分页）+ 分页数据表格</li><li><strong>By Celltype</strong>：差异基因分析，按细胞类型分组</li><li><strong>Tumor vs Normal</strong>：肿瘤与正常组织对比的差异基因分析</li></ul><p>所有选项卡均提供基因搜索框（自动补全）。</p><h3 id="kegg-pathway-kegg-通路富集分析" tabindex="-1">KEGG Pathway（KEGG 通路富集分析） <a class="header-anchor" href="#kegg-pathway-kegg-通路富集分析" aria-label="Permalink to “KEGG Pathway（KEGG 通路富集分析）”">​</a></h3><ul><li>KEGG 通路富集气泡图</li><li>展示差异基因在各通路中的富集情况</li></ul><h3 id="ridge-ranking-ridge-排名图" tabindex="-1">Ridge Ranking（Ridge 排名图） <a class="header-anchor" href="#ridge-ranking-ridge-排名图" aria-label="Permalink to “Ridge Ranking（Ridge 排名图）”">​</a></h3><ul><li>Ridge 排名可视化，展示基因在不同条件下的排名分布</li></ul><h3 id="trajectory-轨迹分析" tabindex="-1">Trajectory（轨迹分析） <a class="header-anchor" href="#trajectory-轨迹分析" aria-label="Permalink to “Trajectory（轨迹分析）”">​</a></h3><p>两个子模块：</p><ul><li><strong>Cell Trajectory（细胞轨迹图）</strong>：按 Cell Type / Plot Type 筛选的细胞轨迹可视化</li><li><strong>Interactive Pseudotime（交互式伪时间分析）</strong>： <ul><li>By State 模式：按细胞状态着色</li><li>By Pseudotime 模式：按伪时间着色</li><li>Gene Expression 模式：选择基因后按表达水平着色（支持基因自动补全）</li></ul></li></ul><h3 id="cellchat-细胞通讯分析" tabindex="-1">CellChat（细胞通讯分析） <a class="header-anchor" href="#cellchat-细胞通讯分析" aria-label="Permalink to “CellChat（细胞通讯分析）”">​</a></h3><p>三个子模块：</p><ul><li><strong>All Interactions</strong>：全量细胞通讯网络图</li><li><strong>Biomarker as Ligand</strong>：特定基因作为配体的网络（基因自动补全）</li><li><strong>Biomarker as Receptor</strong>：特定基因作为受体的网络（基因自动补全）</li></ul><h3 id="network-sensitivity-网络敏感性分析" tabindex="-1">Network Sensitivity（网络敏感性分析） <a class="header-anchor" href="#network-sensitivity-网络敏感性分析" aria-label="Permalink to “Network Sensitivity（网络敏感性分析）”">​</a></h3><ul><li>基因搜索框（自动补全）</li><li>展示选定基因的网络敏感性 PRS 分析结果</li></ul><h3 id="predictive-ability-预测能力-roc-分析" tabindex="-1">Predictive Ability（预测能力 ROC 分析） <a class="header-anchor" href="#predictive-ability-预测能力-roc-分析" aria-label="Permalink to “Predictive Ability（预测能力 ROC 分析）”">​</a></h3><p>两个选项卡：</p><ul><li><strong>Tumor vs Normal</strong>：肿瘤 vs 正常组织的 ROC 曲线</li><li><strong>By Celltype</strong>：按细胞类型的 ROC 曲线</li></ul><p>功能特性：</p><ul><li>基因搜索框（自动补全）</li><li>AUC 筛选过滤</li><li>ROC 曲线与 AUC 数值展示</li></ul><h2 id="clinical-临床分析" tabindex="-1">Clinical（临床分析） <a class="header-anchor" href="#clinical-临床分析" aria-label="Permalink to “Clinical（临床分析）”">​</a></h2><h3 id="survival-生存分析" tabindex="-1">Survival（生存分析） <a class="header-anchor" href="#survival-生存分析" aria-label="Permalink to “Survival（生存分析）”">​</a></h3><p>路径：<code>/clinical/survival</code></p><ul><li>Kaplan-Meier 生存曲线</li><li>支持筛选基因和临床参数</li><li>按分组展示生存差异</li></ul><h3 id="immune-免疫浸润" tabindex="-1">Immune（免疫浸润） <a class="header-anchor" href="#immune-免疫浸润" aria-label="Permalink to “Immune（免疫浸润）”">​</a></h3><p>路径：<code>/clinical/immune</code></p><ul><li>免疫浸润热力图（全量数据渲染）</li><li>图表高度 800px，横坐标标签旋转 45 度</li></ul><h2 id="数据导出选项" tabindex="-1">数据导出选项 <a class="header-anchor" href="#数据导出选项" aria-label="Permalink to “数据导出选项”">​</a></h2><h3 id="导出格式" tabindex="-1">导出格式 <a class="header-anchor" href="#导出格式" aria-label="Permalink to “导出格式”">​</a></h3><ul><li><strong>CSV/Excel</strong>：用于电子表格分析</li><li><strong>PNG/SVG</strong>：用于出版级图形</li></ul>',42)]))}const u=a(t,[["render",n]]);export{p as __pageData,u as default};
